#!/usr/bin/env bash
#
# A wizard — walks a human through a manual procedure step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library — delightful, consistent UX. Identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear — wipe the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" — opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later — it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" — clear the screen, then announce a stage and show progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." — a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." — a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL — open in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser — visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser — visit it manually: $url"
}

# pause "msg" — wait for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" — y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY — current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" — read a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" — like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE — upsert KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE — set a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name — gh not ready; set it later"
}

# set_var NAME VALUE — set a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name — gh not ready; set it later"
}

# finish — clear, then a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}
# ──────────────────────────────────────────────────────────────────────────
# STAGES — 上線回填精靈。部署到 Vercel 之後，剩下的三件只有人能做：
# LINE 的 webhook URL、LIFF 的 endpoint URL、還有 GEMINI_API_KEY（＋可選 XAI_API_KEY），
# 以及可選的「加入好友管道」網址（要量分享頁帶進來幾個真的加好友才需要）。
# ──────────────────────────────────────────────────────────────────────────

ENV_FILE="$(cd "$(dirname "$0")/.." && pwd)/.env.local"
# 網域一定要是你自己的:先看環境變數,再看 .env.local。兩邊都沒有就停——
# 預設成線上版的網域,會帶人把自己的 LINE webhook 指到別人的伺服器。
BASE_URL="${APP_BASE_URL:-$(_existing APP_BASE_URL || true)}"
BASE_URL="${BASE_URL%/}"
if [[ -z "$BASE_URL" ]]; then
  warn "還不知道你的站在哪個網址。先部署到 Vercel,把網址填進 .env.local 的 APP_BASE_URL"
  warn "(例如 APP_BASE_URL=https://你的專案.vercel.app),再重跑這支。步驟見 SETUP.md。"
  exit 1
fi
TOTAL_STAGES=9

banner "成事所 · 上線回填精靈"

stage "GEMINI_API_KEY（LLM 校正與重點抽取）＋ XAI_API_KEY（可選）"
say "pipeline 的校正跟重點抽取以 Gemini 為主體（AI_PROVIDER=google）。"
say "沒有 GEMINI_API_KEY，會議會轉寫成功但抽不出重點、記錄頁重點區是空的。"
open_url "https://aistudio.google.com/apikey"
step "建一把 key，複製回來。"
ask_secret GEMINI_API_KEY "貼上 GEMINI_API_KEY："
if [[ -n "${GEMINI_API_KEY:-}" ]]; then
  write_env GEMINI_API_KEY "$GEMINI_API_KEY"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$GEMINI_API_KEY" | vercel env add GEMINI_API_KEY production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("vercel env add GEMINI_API_KEY production（手動再推一次）")
    warn "vercel env add 失敗，稍後手動補"
  fi
else
  SKIPPED+=("GEMINI_API_KEY 還沒填")
fi
printf '\n'
say "Grok 是第二家（比較用；正式要用再把 AI_PROVIDER 改 grok）。沒有就直接 Enter 跳過。"
open_url "https://console.x.ai/"
ask_secret XAI_API_KEY "貼上 XAI_API_KEY（可空）："
if [[ -n "${XAI_API_KEY:-}" ]]; then
  write_env XAI_API_KEY "$XAI_API_KEY"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$XAI_API_KEY" | vercel env add XAI_API_KEY production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  fi
fi
note "兩把 key 都在之後，跑 pnpm bakeoff:llm 比兩家 flash 級的效果與成本，再決定 AI_MODEL。"

stage "Messaging API 的 webhook URL"
say "LINE 收到訊息會 POST 到這個網址；沒設，官方帳號收到錄音會石沉大海。"
open_url "https://developers.line.biz/console/"
step "進 provider「成事所」→ Messaging API channel → 分頁「Messaging API」"
step "Webhook URL 填：${BOLD}${BASE_URL}/api/line/webhook${RESET}"
step "按「Verify」——要看到 Success（伺服器已上線，驗簽會回 200）"
step "「Use webhook」切到 ON"
pause "設好、Verify 過了再按 Enter"

stage "LIFF 的 endpoint URL"
say "記錄頁連結是 LIFF 深連結（liff.line.me/{LIFF_ID}），LINE 會用 endpoint 去開你的頁面。"
open_url "https://developers.line.biz/console/"
step "進 provider「成事所」→ LINE Login channel → 分頁「LIFF」→ 點進那個 LIFF app"
step "Endpoint URL 改成：${BOLD}${BASE_URL}${RESET}（網域根，後面不要帶 /m）"
note "深連結是 liff.line.me/{LIFF_ID}/m/{id}，LINE 會把 /m/{id} 原樣接在 endpoint 後面；"
note "endpoint 若填成 …/m 會變 /m/m/{id} → 404（第一次上線就踩過）。"
step "Scope 確認有勾 openid、profile；Size 建議 Full"
pause "改好按 Enter"

stage "圖文選單與歡迎訊息（issue #18）"
say "聊天室下方的四格圖文選單（怎麼傳錄音／看範例／額度／方案）由腳本一鍵設定，"
say "用的是 .env.local 的 LINE_CHANNEL_ACCESS_TOKEN，可重複跑。"
if confirm "現在跑 pnpm setup:richmenu？"; then
  if pnpm setup:richmenu; then
    printf '  %s✓ 圖文選單已上%s\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("pnpm setup:richmenu 沒跑成（聊天室下方不會有選單，修好手動再跑）")
    warn "setup:richmenu 失敗，稍後手動再跑"
  fi
else
  SKIPPED+=("pnpm setup:richmenu 還沒跑（聊天室下方不會有選單）")
fi
printf '\n'
say "加好友的歡迎訊息改由 webhook 回（帶四顆 Quick Reply）。LINE 後台預設的"
say "加入好友訊息要關掉，不然新朋友會一次收到兩份。"
open_url "https://manager.line.biz/"
step "進「成事所」帳號 → 聊天室相關 →「加入好友的歡迎訊息」→ 停用"
step "手機驗收：封鎖再解除封鎖官方帳號——要看到歡迎訊息＋四顆按鈕＋底部圖文選單"
step "四格各點一次：教學／範例連結／額度卡／付款卡，都要有回應"
pause "設好、驗過按 Enter"

stage "分享頁的「加入好友管道」網址（可選）"
say "分享頁底部有一顆加好友 CTA，點擊走 /join?ref=share，我們自己記一筆點擊（pnpm metrics 看得到）。"
say "但「點了」不等於「真的加了好友」——後者只有 LINE OA 後台的「加入好友管道」數得到。"
say "開一條專屬網址填進來，那顆 CTA 就改跳它，兩個數字都有；不填也能用，只是少了真加好友數。"
open_url "https://manager.line.biz/"
step "進「成事所」帳號 → 左側「擴充功能」→「加入好友管道」（Add friend routes）"
step "新增一條，名稱取「分享頁」，複製它給的網址"
ask LINE_ADD_FRIEND_URL_SHARE "貼上「分享頁」管道網址（可空）："
if [[ -n "${LINE_ADD_FRIEND_URL_SHARE:-}" ]]; then
  write_env LINE_ADD_FRIEND_URL_SHARE "$LINE_ADD_FRIEND_URL_SHARE"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$LINE_ADD_FRIEND_URL_SHARE" | vercel env add LINE_ADD_FRIEND_URL_SHARE production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("vercel env add LINE_ADD_FRIEND_URL_SHARE production（手動再推一次）")
    warn "vercel env add 失敗，稍後手動補"
  fi
else
  note "跳過。分享頁 CTA 照樣運作，跳一般加好友連結，只有點擊數。"
fi

stage "示範記錄頁的「加入好友管道」網址（可選）"
say "首頁「看一份真的記錄頁」開的示範頁（/demo）底部也有一顆加好友 CTA，走 /join?ref=demo。"
say "跟分享頁同一套道理，開一條專屬網址就數得到真加好友；兩條迴路要分開開，數字才不會混。"
step "同一個「加入好友管道」頁面，再新增一條，名稱取「示範頁」，複製它給的網址"
ask LINE_ADD_FRIEND_URL_DEMO "貼上「示範頁」管道網址（可空）："
if [[ -n "${LINE_ADD_FRIEND_URL_DEMO:-}" ]]; then
  write_env LINE_ADD_FRIEND_URL_DEMO "$LINE_ADD_FRIEND_URL_DEMO"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$LINE_ADD_FRIEND_URL_DEMO" | vercel env add LINE_ADD_FRIEND_URL_DEMO production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("vercel env add LINE_ADD_FRIEND_URL_DEMO production（手動再推一次）")
    warn "vercel env add 失敗，稍後手動補"
  fi
else
  note "跳過。示範頁 CTA 照樣運作，跳一般加好友連結，只有點擊數。"
fi
pause "按 Enter 繼續"

stage "Stripe 付費牆（兩檔訂閱）"
say "掛 海外公司 收款。四個值都齊了付費牆才會動；缺任何一個，撞額度的人只會收到"
say "「方案正在開通中」而拿不到付款連結（程式不會壞，但也收不到錢）。"
open_url "https://dashboard.stripe.com/products"
step "建兩個 Product，各一個「Recurring / 每月」的 price，幣別 TWD："
step "  ・輕量 NT$99/月　・標準 NT$399/月"
step "複製兩個 price id（price_ 開頭，不是 prod_）"
ask STRIPE_PRICE_LITE "貼上輕量檔的 price id："
ask STRIPE_PRICE_STANDARD "貼上標準檔的 price id："
for k in STRIPE_PRICE_LITE STRIPE_PRICE_STANDARD; do
  v="${!k:-}"
  if [[ -n "$v" ]]; then
    write_env "$k" "$v"
    if command -v vercel >/dev/null 2>&1 && printf '%s' "$v" | vercel env add "$k" production --force >/dev/null 2>&1; then
      printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
    else
      SKIPPED+=("vercel env add $k production（手動再推一次）")
    fi
  else
    SKIPPED+=("$k 還沒填（付費牆發不出付款連結）")
  fi
done
printf '\n'
open_url "https://dashboard.stripe.com/apikeys"
step "複製 Secret key（sk_live_ 開頭；先測可以用 sk_test_）"
ask_secret STRIPE_SECRET_KEY "貼上 STRIPE_SECRET_KEY："
if [[ -n "${STRIPE_SECRET_KEY:-}" ]]; then
  write_env STRIPE_SECRET_KEY "$STRIPE_SECRET_KEY"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$STRIPE_SECRET_KEY" | vercel env add STRIPE_SECRET_KEY production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("vercel env add STRIPE_SECRET_KEY production（手動再推一次）")
  fi
else
  SKIPPED+=("STRIPE_SECRET_KEY 還沒填")
fi
printf '\n'
open_url "https://dashboard.stripe.com/webhooks"
step "Add endpoint，URL 填：${BOLD}${BASE_URL}/api/stripe/webhook${RESET}"
step "事件只勾這三個：customer.subscription.created / updated / deleted"
note "少勾的話錢收得到但權益不會開通——訂閱狀態全靠這三個事件同步回來。"
step "建好後點進去，「Signing secret」→ Reveal，複製 whsec_ 開頭那串"
ask_secret STRIPE_WEBHOOK_SECRET "貼上 STRIPE_WEBHOOK_SECRET："
if [[ -n "${STRIPE_WEBHOOK_SECRET:-}" ]]; then
  write_env STRIPE_WEBHOOK_SECRET "$STRIPE_WEBHOOK_SECRET"
  if command -v vercel >/dev/null 2>&1 && printf '%s' "$STRIPE_WEBHOOK_SECRET" | vercel env add STRIPE_WEBHOOK_SECRET production --force >/dev/null 2>&1; then
    printf '  %s✓ 已推到%s Vercel production\n' "$GREEN" "$RESET"
  else
    SKIPPED+=("vercel env add STRIPE_WEBHOOK_SECRET production（手動再推一次）")
  fi
else
  SKIPPED+=("STRIPE_WEBHOOK_SECRET 還沒填（權益不會自動開通）")
fi
printf '\n'
open_url "https://dashboard.stripe.com/settings/billing/portal"
step "把 Customer portal 打開（存一次設定即可）——LINE 傳「訂閱」拿到的管理連結靠它"
pause "四個值都填好按 Enter"

stage "R2 音檔的保險絲（object lifecycle）"
say "音檔真刪目前完全靠 cron（每天 03:00 台北跑一次 /api/cron/cleanup）。"
say "cron 要是靜默失敗，音檔不是晚點刪，是永遠留著——而「真刪」是寫在首頁跟"
say "GLOSSARY.md 的承諾。後台加一條 lifecycle 當保險絲，兜住這個失敗模式。"
note "設 7 天而不是 3 天：cron 正常時最慢 96 小時（72h TTL＋最多 24h 等下一次 cron）"
note "就刪完了，保險絲要明顯寬於它，平時輪不到它動手，才不會搶在 cron 前面砍掉還沒到期的音檔。"
open_url "https://dash.cloudflare.com/?to=/:account/r2/default/buckets/${R2_BUCKET:-chengshisuo-audio}/settings"
step "Settings → Object Lifecycle Rules → Add"
step "Rule name：7 days delete（正式站用的名字；叫什麼都行，作用看下面兩行）"
step "prefix 留空（整個 bucket 都是音檔）"
step "只勾「Delete uploaded objects after」，填 7 Days，存檔"
note "存完列表上應該有兩條：這條，加上建 bucket 時就有的 Default Multipart Abort Rule"
note "（後者只清沒收尾的 multipart upload，不碰已完成的物件——我們是單發 PUT，碰不到它）。"
warn "別設成短於 72 小時：那會蓋過產品的 TTL，使用者在期限內回頭聽會變成「錄音已刪除」。"
pause "設好按 Enter"

stage "端對端試一場"
say "最後一關，真的丟一段錄音給官方帳號。"
step "手機 LINE 打開「成事所」官方帳號（ID：$(_existing NEXT_PUBLIC_LINE_OA_ID || echo '見 .env.local')）"
step "傳一段 1–2 分鐘的錄音（語音訊息或分享 m4a 都可以）"
step "應該先收到「收件」回覆，幾分鐘後收到記錄頁連結"
step "點開連結——會在 LINE 內開 LIFF，看到自己的會議、能改說話人、能自動存"
step "產一條分享連結，用無痕視窗開它，捲到最底點「把你的會議也丟給成事所」——要落在加好友頁"
note "回頭跑 pnpm metrics，「加好友 CTA 點擊」那段要看到一筆 share。"
step "傳一句「升級」——要收到兩檔的付款連結；用測試卡付一次，幾秒內要收到開通通知"
note "卡在哪一步就是哪一環沒接上：沒回覆＝webhook；有連結但打不開＝LIFF endpoint；"
note "有記錄但重點是空的＝GEMINI_API_KEY；付了款沒開通＝Stripe webhook 的事件沒勾齊。"
pause "跑過一遍後按 Enter"

finish
